from rendu import Point
p=Point(10)
p.h('10.1 — Si le membre est menacé, traiter la menace avant de classer la déformation')
p.p('Si traumatisme avec fracture ouverte, souffrance cutanée ou déficit neurovasculaire → appeler immédiatement l’équipe orthopédique ou de chirurgie de la main ; documenter peau, nerfs et circulation, obtenir les clichés adaptés et organiser réduction et traitement de l’ouverture. La déformation radiographique ne doit pas détourner de la viabilité du membre.', ['p82-radius','pa82-radius-urgences'])
p.p('Si absence de pouls, saignement persistant ou hématome expansif → rechercher une lésion vasculaire ; si ces signes persistent après réalignement ou réduction → exploration immédiate. Une recoloration conservée ou un Doppler positif ne ferme pas cette branche.', 'pa82-radius-ischemie')
p.p('Si articulation rouge, chaude, douloureuse ou avec épanchement → envisager une arthrite septique même sans fièvre ; si sepsis ou choc → prise en charge immédiate. Sinon, obtenir le prélèvement articulaire diagnostique avant l’antibiothérapie empirique.', ['pa82-arthrite-suspecte','pa82-arthrite-ponction'])
p.h('10.2 — Si le pied diabétique neuropathe est chaud et gonflé, le protéger pendant le bilan')
p.p('Si diabète, neuropathie, peau intacte et pied plus chaud, rouge ou gonflé que l’autre → considérer un Charcot actif, immobiliser et décharger jusqu’au genou sans attendre la fin des investigations. Demander radiographies du pied et de la cheville, idéalement bilatérales.', ['pa82-charcot-r1','pa82-charcot-r5','pa82-charcot-r6'])
p.p('Si radiographies normales mais suspicion persistante → IRM ; si IRM impossible → scintigraphie, scanner ou SPECT-CT selon disponibilité. Des marqueurs sanguins normaux ne permettent pas d’exclure cette affection sur peau intacte.', ['pa82-charcot-r8','pa82-charcot-r9','pa82-charcot-r10'])
p.h('10.3 — Si l’enfant présente une déformation, chercher d’abord douleur, rigidité et progression')
p.p('Si boiterie aiguë atraumatique avec altération générale, fièvre, impossibilité d’appui, douleur passive sévère ou douleur nocturne → investigation urgente pour cause infectieuse, maligne ou autre affection grave. Ne pas attribuer ces signes à une simple variante d’axe.', ['pa82-enfant-alarmes','pa82-enfant-action'])
p.p('Si pied plat souple, indolore et fonctionnel, avec arche se reformant hors charge ou sur la pointe des pieds → information et observation clinique ; pas d’imagerie ni d’orthèse prophylactique systématique. Si douleur, rigidité ou asymétrie → évaluation ciblée et imagerie selon indication.', ['p82-plat-examen','pa82-plat-europe-imagerie','pa82-plat-europe-prevention'])
p.p('Si désaxation du genou symétrique compatible avec l’évolution physiologique → surveillance ; si varum après deux ans, valgum marqué après huit ans, asymétrie ou aggravation → orientation spécialisée. Si signes de rachitisme, retard statural disproportionné ou contexte familial → bilan phosphocalcique adapté à l’âge et recherche d’XLH selon le mécanisme.', ['p82-genou','pa82-genou-orientation','p82-xlh-clinique','p82-xlh-mecanisme-bilan'])
p.h('10.4 — Si la déformation est rachidienne, distinguer dépistage et confirmation')
p.p('Si asymétrie du tronc → test d’Adams et scoliomètre ; si rotation du tronc au seuil d’investigation suisse → radiographie du rachis entier debout et mesure du Cobb. Si examen clinique et scoliomètre normaux → pas de cliché de référence systématique.', ['p82-scoliose-clinique','p82-scoliose-radio','pa82-scoliose-normalite'])
p.p('Si douleur persistante, anomalie neurologique ou courbure atypique → recherche d’une cause secondaire avec IRM selon indication. Si scoliose confirmée chez un adolescent en croissance → suivi et décision de traitement fondés sur courbure et croissance restante.', ['p82-scoliose-irm','p82-scoliose-definition'])
p.h('10.5 — Si la main ou l’avant-pied se déforme sans urgence, identifier le tissu concerné')
p.p('Si douleur de main liée à l’utilisation et déformation articulaire → examen complet, puis imagerie ciblée et traitement fonctionnel de l’arthrose. Si cordes palmaires et test de la table positif → Dupuytren, habituellement clinique. Si perte d’extension active distale après traumatisme → maillet, avec recherche de plaie et d’avulsion osseuse.', ['p82-arthrose','p82-arthrose-diagnostic','pa82-dupuytren-table','pa82-dupuytren-examens','pa82-maillet-actif','pa82-maillet-seymour'])
p.p('Si maillet ouvert → prise en charge spécialisée le jour même ; si fermé → consultation selon la filière BSSH dans les soixante-douze heures. Si hallux valgus gênant → évaluer chaussage, douleur, réductibilité et mobilité, puis radiographies en charge si nécessaires à la décision.', ['pa82-maillet-delai','p82-hallux','pa82-hallux-examen','pa82-hallux-imagerie'])
p.sauver()
